// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0) && rewardToken != address(c));
        // Ensure rewardToken hasn't been added yet (lastUpdateTime == 0)
        // We can't read internal _balances or rewardData directly; we call addReward which will revert if already exists.
        // But to make it general, we need a fresh token each run. Use vm.assume: not zero, not the contract itself.
        // addReward might revert if token already exists; that's fine, we only assert when it succeeds.
        // We'll call addReward and then check totalSupply.
        // Since no stake happened, totalSupply() should be 0 in reference, but in mutant it returns 1.
        c.addReward(rewardToken);
        assertTrue(c.totalSupply() == 0, "totalSupply should be 0 after addReward with no stakes");
    }
}

